DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='selected_trip_export';f:=replace(f,'NOT BETWEEN 1 AND 15','NOT BETWEEN 1 AND 18');f:=replace(f,'''pickup_zip'',''dropoff_zip''','''pickup_zip'',''dropoff_zip'',''timezone_review''');f:=replace(f,'pickup_zip,dropoff_zip FROM public.trips','pickup_zip,dropoff_zip,CASE WHEN public.regional_trip_interval(trips) IS NULL THEN ''Timezone review required'' ELSE ''Verified local events'' END AS timezone_review FROM public.trips');EXECUTE f;
SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='customer_selected_request_export'; f:=replace(f,'''time'',r.pickup_time','''time'',r.pickup_time,''timezone_review'',CASE WHEN r.regional_time_events IS NULL OR jsonb_array_length(r.regional_time_events)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.regional_time_events) e WHERE e->>''status'' IS DISTINCT FROM ''resolved'') THEN ''Timezone review required'' ELSE ''Verified local events'' END');f:=replace(f,'''reference'',''date'',''time''','''reference'',''date'',''time'',''timezone_review''');EXECUTE f;
SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='patient_request_snapshot';f:=replace(f,'''pickup_timezone'',''dropoff_timezone''','''pickup_timezone'',''dropoff_timezone'',''regional_time_events''');EXECUTE f; END $$;
CREATE FUNCTION public.people_regional_value_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r jsonb:=to_jsonb(NEW);s text;z text;postal text; BEGIN s:=CASE WHEN TG_TABLE_NAME='payers' THEN r->>'billing_state' ELSE r->>'state' END;z:=CASE WHEN TG_TABLE_NAME='payers' THEN r->>'billing_timezone' ELSE r->>'timezone' END;postal:=CASE WHEN TG_TABLE_NAME='payers' THEN r->>'billing_zip' ELSE r->>'zip' END;IF coalesce(s,'')<>'' AND NOT public.us_state_catalog() ? s THEN RAISE EXCEPTION 'Supported U.S. state required';END IF;IF coalesce(z,'')<>'' AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=z) THEN RAISE EXCEPTION 'Valid IANA timezone required';END IF;IF coalesce(postal,'')<>'' AND postal !~ '^\d{5}(-\d{4})?$' THEN RAISE EXCEPTION 'Valid ZIP required';END IF;RETURN NEW;END $$;
CREATE TRIGGER patient_regional_values BEFORE INSERT OR UPDATE OF state,zip,timezone ON public.saved_patients FOR EACH ROW EXECUTE FUNCTION public.people_regional_value_guard();
CREATE TRIGGER contact_regional_values BEFORE INSERT OR UPDATE OF state,zip,timezone ON public.provider_contacts FOR EACH ROW EXECUTE FUNCTION public.people_regional_value_guard();
CREATE TRIGGER payer_regional_values BEFORE INSERT OR UPDATE OF billing_state,billing_zip,billing_timezone ON public.payers FOR EACH ROW EXECUTE FUNCTION public.people_regional_value_guard();